INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('472b4efa-7871-4b84-9408-f8648827b981', 'c2632427-9fab-55ae-b85f-a8fdec962a91', $$Mini-Grid Tariff Study, Volta and Northern Regions$$, $$Energy Commission of Ghana$$, NULL, 2019, 2020, $$Lead Analyst$$, $$Modelled cost-reflective tariffs for 55 solar mini-grids on island and lakeside communities and proposed a cross-subsidy mechanism.$$, $$Tariff framework adopted by the regulator; three private developers entered the market.$$, $$[{"url":"https://picsum.photos/seed/demo-kwabena-owusu-ansah-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-kwabena-owusu-ansah-portfolio-1-img1/900/600","caption":"Island mini-grid on Lake Volta"},{"url":"https://picsum.photos/seed/demo-kwabena-owusu-ansah-portfolio-1-img2/900/600","caption":"Tariff consultation in Tamale"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('8f37dd4c-5865-4e99-8058-5ca709636a4b', 'c2632427-9fab-55ae-b85f-a8fdec962a91', $$Results-Based Financing for Efficient Cooling, Nigeria$$, $$Clean Energy Fund (multi-donor)$$, NULL, 2022, 2023, $$Financial Modeling Lead$$, $$Designed incentive levels and financial models for a results-based financing window supporting energy-efficient cold storage for traders.$$, $$Window launched with 14 participating companies and 2,100 cold rooms planned.$$, $$[{"url":"https://picsum.photos/seed/demo-kwabena-owusu-ansah-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-kwabena-owusu-ansah-portfolio-2-img1/900/600","caption":"Solar cold room in a Lagos market"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('a15c9090-c8c6-59f6-8e95-bbcd0bd66ec0', 'c2632427-9fab-55ae-b85f-a8fdec962a91', $$Off-Grid Solar Market Assessment, Sierra Leone$$, $$African Development Bank$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2023, 2024, $$Energy Finance Lead$$, $$Assessed demand, affordability and distribution channels for solar home systems and productive-use equipment in Sierra Leone, and sized a results-based financing window for companies selling to rural households.$$, $$Financing window of USD 12 million approved; nine companies prequalified.$$, $$[{"url":"https://picsum.photos/seed/demo-kwabena-owusu-ansah-off-grid-solar-market-assessment-sierra--1/900/600","caption":"Solar retailer interview in Bo"},{"url":"https://picsum.photos/seed/demo-kwabena-owusu-ansah-off-grid-solar-market-assessment-sierra--2/900/600","caption":"Household affordability survey"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
