INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('5eccd77c-95d3-41ec-b948-d92cc4720625', '48326172-4dfb-5062-acb1-ee44eb766ee2', $$Cabo Delgado Recovery Consultations$$, $$UNDP Mozambique$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2023, $$Lead Interpreter$$, $$Interpreted community consultations and coordination meetings on recovery and reconstruction for displaced and host communities in Cabo Delgado.$$, $$More than 60 consultations interpreted; consultation summaries translated for donors within 48 hours.$$, $$[{"url":"https://picsum.photos/seed/demo-celso-mabunda-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-celso-mabunda-portfolio-1-img1/900/600","caption":"Community consultation in Pemba"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('96193a64-db49-486f-8871-2d84c21bf123', '48326172-4dfb-5062-acb1-ee44eb766ee2', $$Cyclone Idai Response Translation and Localization$$, $$International Federation of Red Cross and Red Crescent Societies$$, (SELECT id FROM organizations WHERE name = $$IFRC$$), 2019, 2019, $$Translation Coordinator$$, $$Coordinated translation and localization of health and shelter messages into Portuguese and local languages during the Cyclone Idai response.$$, $$Messages reached affected communities in Sofala within the first two weeks.$$, $$[{"url":"https://picsum.photos/seed/demo-celso-mabunda-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-celso-mabunda-portfolio-2-img1/900/600","caption":"Translated shelter messages in Beira"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('88b03060-3759-51a9-8b0f-4a51afa0d705', '48326172-4dfb-5062-acb1-ee44eb766ee2', $$Disaster Preparedness Glossary in Portuguese and Local Languages$$, $$UNDRR$$, (SELECT id FROM organizations WHERE name = $$UNDRR$$), 2021, 2021, $$Lead Translator and Editor$$, $$Compiled and edited a glossary of 300 disaster risk terms in Portuguese, Emakhuwa, Sena and Changana for early warning messages and community training, working with radio presenters and local committees.$$, $$Glossary used in national early warning messages since the 2022 cyclone season.$$, $$[{"url":"https://picsum.photos/seed/demo-celso-mabunda-disaster-preparedness-glossary-in-portug-1/900/600","caption":"Terminology workshop with radio presenters"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
