INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('f69aa54b-f7ad-4db6-9fbb-11fa604ac992', '15212843-500f-540b-b3a1-32e16a2b00b6', $$Electric Bus Gross-Cost Contracts, Three Indian Cities$$, $$State transport undertakings$$, NULL, 2021, 2023, $$Transaction Advisor$$, $$Structured gross-cost contracts for 1,200 electric buses, including financial modeling, risk allocation and bid process management.$$, $$Contracts awarded with per-kilometre costs 18% below benchmarks.$$, $$[{"url":"https://picsum.photos/seed/demo-arjun-raghavan-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-arjun-raghavan-portfolio-1-img1/900/600","caption":"Electric bus depot in Chennai"},{"url":"https://picsum.photos/seed/demo-arjun-raghavan-portfolio-1-img2/900/600","caption":"Bid conference"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('04e03aa4-9194-403e-803a-7a33250637ac', '15212843-500f-540b-b3a1-32e16a2b00b6', $$Street Lighting Energy Efficiency PPP, Colombo$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2018, 2019, $$PPP Specialist$$, $$Prepared an energy savings performance contract for LED street lighting.$$, $$Projected 55% energy savings; contract signed in 2020.$$, $$[{"url":"https://picsum.photos/seed/demo-arjun-raghavan-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-arjun-raghavan-portfolio-2-img1/900/600","caption":"LED street lighting pilot"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('134ab4f1-a6e9-5480-bfb5-bd6a6b02499a', '15212843-500f-540b-b3a1-32e16a2b00b6', $$Transit-Oriented Development Value Capture Study, Ahmedabad$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2019, 2020, $$PPP and Finance Advisor$$, $$Estimated land value uplift around new metro stations in Ahmedabad and designed value capture instruments, including betterment levies and premium floor area charges, to co-finance station-area infrastructure.$$, $$Premium floor area charge adopted in the city's revised development plan.$$, $$[{"url":"https://picsum.photos/seed/demo-arjun-raghavan-transit-oriented-development-value-captu-1/900/600","caption":"Station-area site visit"},{"url":"https://picsum.photos/seed/demo-arjun-raghavan-transit-oriented-development-value-captu-2/900/600","caption":"Value capture workshop with the city"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
