INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('bff3835f-2eb0-46e2-8dbb-949026baba93', '6d682be3-84e0-5676-b195-2b603655c7e8', $$Gender Budget Tagging, Punjab Development Programme$$, $$UN Women Pakistan$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2022, 2023, $$Budget Analyst$$, $$Tagged 2,400 development projects for gender relevance and analysed allocations by sector.$$, $$Tagging method adopted in the provincial budget call circular.$$, $$[{"url":"https://picsum.photos/seed/demo-mehwish-tariq-khan-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mehwish-tariq-khan-portfolio-1-img1/900/600","caption":"Budget tagging workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('1d8c9480-1495-4ff9-9e8f-e72a2e9db960', '6d682be3-84e0-5676-b195-2b603655c7e8', $$Public Spending on Girls' Secondary Schooling$$, $$Lahore policy institute$$, NULL, 2021, 2022, $$Research Associate$$, $$Analysed district spending on girls' secondary schools against enrolment data.$$, $$Policy brief cited in the provincial assembly's education committee.$$, $$[{"url":"https://picsum.photos/seed/demo-mehwish-tariq-khan-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mehwish-tariq-khan-portfolio-2-img1/900/600","caption":"District spending chart"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('bbc23bc2-496a-5337-bb60-df7cc583d337', '6d682be3-84e0-5676-b195-2b603655c7e8', $$Maternal Health Spending Review, Punjab$$, $$UNFPA$$, (SELECT id FROM organizations WHERE name = $$UNFPA$$), 2023, 2024, $$Budget Analyst$$, $$Traced provincial and district spending on maternal and newborn health over five years, compared budgets with actual spending, and visualised the gaps for the provincial assembly's health committee.$$, $$Committee recommended ring-fenced funding for basic emergency obstetric care in the next budget.$$, $$[{"url":"https://picsum.photos/seed/demo-mehwish-tariq-khan-maternal-health-spending-review-punjab-1/900/600","caption":"Briefing for the health committee"},{"url":"https://picsum.photos/seed/demo-mehwish-tariq-khan-maternal-health-spending-review-punjab-2/900/600","caption":"Spending dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
