INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('238568e0-bad1-48a4-a4fe-35db93037774', '2cc721e1-3404-5ce7-8b4f-51160ace6bd9', $$Inclusive Education Training of Trainers, Koshi Province$$, $$Humanity & Inclusion$$, (SELECT id FROM organizations WHERE name = $$Humanity & Inclusion$$), 2017, 2019, $$Coordinator$$, $$Designed and delivered a training of trainers programme on inclusive teaching for 120 resource teachers.$$, $$Resource teachers trained 1,900 classroom teachers; enrolment of children with disabilities rose in pilot schools.$$, $$[{"url":"https://picsum.photos/seed/demo-sushila-gurung-thapa-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sushila-gurung-thapa-portfolio-1-img1/900/600","caption":"Training session in Biratnagar"},{"url":"https://picsum.photos/seed/demo-sushila-gurung-thapa-portfolio-1-img2/900/600","caption":"Inclusive classroom"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('5f38540b-0777-4467-bdf7-d1415adcbab2', '2cc721e1-3404-5ce7-8b4f-51160ace6bd9', $$Disability-Inclusive Local Planning Workshops$$, $$UNDP Nepal$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2023, $$Lead Facilitator$$, $$Facilitated workshops between municipalities and organizations of persons with disabilities on inclusive local planning.$$, $$18 municipalities included accessibility budgets in annual plans.$$, $$[{"url":"https://picsum.photos/seed/demo-sushila-gurung-thapa-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sushila-gurung-thapa-portfolio-2-img1/900/600","caption":"Municipal planning workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('15ab62ee-94bc-5716-a923-cd587d791939', '2cc721e1-3404-5ce7-8b4f-51160ace6bd9', $$Organisational Capacity Assessment of Disabled People's Organisations$$, $$CBM$$, (SELECT id FROM organizations WHERE name = $$CBM$$), 2024, 2024, $$Lead Facilitator$$, $$Facilitated participatory organisational capacity assessments with 12 organisations of persons with disabilities in three provinces, covering governance, finance, advocacy and accessibility, and agreed a development plan with each.$$, $$Twelve organisational development plans agreed; four organisations secured municipal funding for the first time.$$, $$[{"url":"https://picsum.photos/seed/demo-sushila-gurung-thapa-organisational-capacity-assessment-of-di-1/900/600","caption":"Assessment workshop in Pokhara"},{"url":"https://picsum.photos/seed/demo-sushila-gurung-thapa-organisational-capacity-assessment-of-di-2/900/600","caption":"Accessible materials review"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
