INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('39ecbaaa-b359-4e52-80fb-efffe822b2b6', 'c6ad355c-52d5-5e44-b063-ad6575f1b8ff', $$Living with Melting Glaciers Photo Essay$$, $$ICIMOD$$, (SELECT id FROM organizations WHERE name = $$ICIMOD$$), 2015, 2016, $$Photographer$$, $$Photo essay on herders and farmers adapting to glacier retreat in Mustang and Solukhumbu.$$, $$Exhibited in Kathmandu and at an international mountain conference.$$, $$[{"url":"https://picsum.photos/seed/demo-rajan-shrestha-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rajan-shrestha-portfolio-1-img1/900/600","caption":"Herder in upper Mustang"},{"url":"https://picsum.photos/seed/demo-rajan-shrestha-portfolio-1-img2/900/600","caption":"Glacial lake at dawn"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('b67117f9-7ae2-4658-9f36-a2e3447eb3d7', 'c6ad355c-52d5-5e44-b063-ad6575f1b8ff', $$Community Forestry Short Documentary$$, $$FAO Nepal$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2023, 2023, $$Director$$, $$Directed a 12-minute documentary with motion graphics on community forestry user groups, subtitled in English and Nepali.$$, $$Screened at a regional forestry week and viewed widely online.$$, $$[{"url":"https://picsum.photos/seed/demo-rajan-shrestha-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rajan-shrestha-portfolio-2-img1/900/600","caption":"Filming with a forest user group"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('639bb7ee-dbcb-5ae1-921d-210dd7c551e6', 'c6ad355c-52d5-5e44-b063-ad6575f1b8ff', $$Community-Based Tourism Visual Guide, Upper Mustang$$, $$SNV$$, (SELECT id FROM organizations WHERE name = $$SNV$$), 2024, 2024, $$Photographer and Editor$$, $$Photographed and edited a visual guide for homestays and community guides in Upper Mustang, and trained six young people from the area in basic photography and social media so they can keep the materials up to date.$$, $$Guide distributed to 40 homestays; trainees now run the communities' booking page.$$, $$[{"url":"https://picsum.photos/seed/demo-rajan-shrestha-community-based-tourism-visual-guide-upp-1/900/600","caption":"Homestay owners in Lo Manthang"},{"url":"https://picsum.photos/seed/demo-rajan-shrestha-community-based-tourism-visual-guide-upp-2/900/600","caption":"Photography training for young guides"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
