-- Farid Ahmad Noori
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('d055316a-fb98-41bb-b1cb-9e67d6b6d2dd', 'eb73efe8-dd02-5d87-837a-fa818d06fdfc', $$Third-Party Monitoring of Food and Cash Assistance$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2021, 2024, $$Monitoring Director$$, $$Directed monitoring of food and cash distributions in 22 provinces, including phone surveys and geotagged site verification.$$, $$Monitoring covered 3,000 distributions a year; findings led to corrections at 14% of sites.$$, $$[{"url":"https://picsum.photos/seed/demo-farid-ahmad-noori-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-farid-ahmad-noori-portfolio-1-img1/900/600","caption":"Distribution site monitoring"},{"url":"https://picsum.photos/seed/demo-farid-ahmad-noori-portfolio-1-img2/900/600","caption":"Monitor training in Herat"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('40ae39f4-ac08-4cbd-a9db-caef8726c74e', 'eb73efe8-dd02-5d87-837a-fa818d06fdfc', $$Rural Infrastructure Verification Survey$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2018, 2020, $$Survey Lead$$, $$Designed the verification survey for community infrastructure sub-projects with women monitors for household interviews.$$, $$Verified 2,600 sub-projects; quality issues flagged were addressed in the next phase.$$, $$[{"url":"https://picsum.photos/seed/demo-farid-ahmad-noori-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-farid-ahmad-noori-portfolio-2-img1/900/600","caption":"Village water scheme inspection"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('63e5fea2-5f2d-522e-b662-588281938f37', 'eb73efe8-dd02-5d87-837a-fa818d06fdfc', $$Remote Verification of Rural Roads with Satellite Imagery$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2022, 2023, $$Monitoring Director$$, $$Combined high-resolution satellite imagery, geotagged photos from community monitors and short phone interviews to verify the completion and condition of rural road works in areas closed to international staff.$$, $$310 road sections verified; verification cost per site cut by half compared with field visits.$$, $$[{"url":"https://picsum.photos/seed/demo-farid-ahmad-noori-remote-verification-of-rural-roads-with--1/900/600","caption":"Satellite comparison of a completed road section"},{"url":"https://picsum.photos/seed/demo-farid-ahmad-noori-remote-verification-of-rural-roads-with--2/900/600","caption":"Community monitor training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6c28368b-20ab-57bd-805d-d7e7dd54cb9c', 'eb73efe8-dd02-5d87-837a-fa818d06fdfc', $$7e5d7aad-4132-4d85-8f07-0e51d913013b$$, NULL, $$Stefan Larsen$$, $$World Bank$$, $$Senior Operations Officer$$, $$client$$, $$slarsen@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2018, 2020, $$Third-party verification of rural infrastructure$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We contracted Farid's firm for third-party monitoring of rural infrastructure, and he personally led the verification survey. He built a remote verification system that worked in places none of us could visit, and his reports were honest about problems. He protected his field teams carefully. I would work with him again on monitoring in fragile settings.$$, $$auto$$, '2026-04-16T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-04-14T16:49:08.421Z'::timestamptz, '2026-04-16T16:34:44.421Z'::timestamptz, '2026-04-16T16:41:56.421Z'::timestamptz, '2026-04-16T16:49:08.421Z'::timestamptz, '2026-04-16T16:49:08.421Z'::timestamptz, '2026-04-17T16:49:08.421Z'::timestamptz, $$9ec8f7eea5229beab8a8ff6036b2c5ba$$, '2026-04-13T16:49:08.421Z'::timestamptz);
