  ('5930297f-d8db-5ebd-8555-a552da0c562e', 'eb73efe8-dd02-5d87-837a-fa818d06fdfc', 'employer', $$7e5d7aad-4132-4d85-8f07-0e51d913013b$$, $$Monitoring Director, Third-party monitoring firm (Kabul), 2016–2024$$, 'f1fe5688', 'document_reviewed', 'document', $${"note":"Demo: contract with most recent client reviewed.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-03-22T19:49:08.421Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-03-22T20:49:08.421Z'::timestamptz),
