-- Sana Rizvi Hussain
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('42d96b03-9d31-4755-9ddd-91d2775a04e9', '98c99227-1ba2-5411-8f38-abb1dab14aad', $$Women-Owned SME Credit Demand Study$$, $$IFC$$, (SELECT id FROM organizations WHERE name = $$International Finance Corporation$$), 2021, 2022, $$Team Leader$$, $$Led market research with 1,500 women-owned businesses and 15 banks on credit demand and lending barriers.$$, $$Three banks launched women-focused SME products after the study.$$, $$[{"url":"https://picsum.photos/seed/demo-sana-rizvi-hussain-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sana-rizvi-hussain-portfolio-1-img1/900/600","caption":"Interview with a women entrepreneur in Hyderabad"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('ba8c1529-80de-4e61-87c5-2cfbda279a29', '98c99227-1ba2-5411-8f38-abb1dab14aad', $$Gender Targets in the National Financial Inclusion Strategy$$, $$State Bank of Pakistan$$, (SELECT id FROM organizations WHERE name = $$State Bank of Pakistan$$), 2019, 2020, $$Advisor$$, $$Advised on gender-disaggregated targets and supporting policies for the financial inclusion strategy.$$, $$Strategy adopted a target of 20 million women with accounts.$$, $$[{"url":"https://picsum.photos/seed/demo-sana-rizvi-hussain-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sana-rizvi-hussain-portfolio-2-img1/900/600","caption":"Strategy launch event"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('d0182ea7-f670-5b6e-9bc8-19a795aed6ed', '98c99227-1ba2-5411-8f38-abb1dab14aad', $$Microinsurance for Women Entrepreneurs, Sindh$$, $$International Labour Organization$$, (SELECT id FROM organizations WHERE name = $$International Labour Organization$$), 2023, 2024, $$Lead Consultant$$, $$Reviewed health and business-interruption microinsurance products offered to women entrepreneurs in Sindh, ran focus groups with clients, and designed simpler product terms and SMS reminders for renewals.$$, $$Renewal rate rose from 38% to 61% in the pilot branches.$$, $$[{"url":"https://picsum.photos/seed/demo-sana-rizvi-hussain-microinsurance-for-women-entrepreneurs-s-1/900/600","caption":"Focus group with women entrepreneurs"},{"url":"https://picsum.photos/seed/demo-sana-rizvi-hussain-microinsurance-for-women-entrepreneurs-s-2/900/600","caption":"Product design workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('88bed346-b833-5e24-a363-55befe582223', '98c99227-1ba2-5411-8f38-abb1dab14aad', $$ce11d637-dc79-4cc4-8f23-3017c0d6d6cd$$, NULL, $$Farah Siddiqui$$, $$International Finance Corporation$$, $$Principal Investment Officer$$, $$supervisor$$, $$fsiddiqui@ifc.org$$, (SELECT id FROM organizations WHERE name = $$International Finance Corporation$$), 2010, 2018, $$SME product development at a commercial bank in Karachi$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I managed Sana at the bank where she ran SME product development, before I joined IFC. She designed our first loan products for women-owned businesses and they performed better than the rest of the portfolio. She combines market research with real banking experience. I would work with her again on financial inclusion and SME finance.$$, $$auto$$, '2026-05-31T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-29T16:49:08.421Z'::timestamptz, '2026-05-31T16:34:44.421Z'::timestamptz, '2026-05-31T16:41:56.421Z'::timestamptz, '2026-05-31T16:49:08.421Z'::timestamptz, '2026-05-31T16:49:08.421Z'::timestamptz, '2026-06-01T16:49:08.421Z'::timestamptz, $$390fd4001d2cd2987f3a11b04d6351bb$$, '2026-05-28T16:49:08.421Z'::timestamptz);
