-- Sreymom Keo
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('72c771e8-ef94-406b-b5b9-8890cd19651d', '580a10e5-1ad7-58bd-8b50-01b7f9c5735a', $$Plastic Waste Flow Analysis, Phnom Penh Markets$$, $$UNDP Cambodia$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2023, $$Research Assistant$$, $$Measured plastic waste generation and recycling in eight markets and interviewed recyclers and waste pickers.$$, $$Findings fed into the city's plastic reduction plan.$$, $$[{"url":"https://picsum.photos/seed/demo-sreymom-keo-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sreymom-keo-portfolio-1-img1/900/600","caption":"Waste sorting at a market"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('fa9b7423-79db-4f07-b92b-b83e5e978778', '580a10e5-1ad7-58bd-8b50-01b7f9c5735a', $$Extended Producer Responsibility Policy Brief$$, $$Cambodian environmental think tank$$, NULL, 2023, 2023, $$Author$$, $$Wrote a policy brief comparing extended producer responsibility schemes in the region.$$, $$Brief presented to the inter-ministerial waste committee.$$, $$[{"url":"https://picsum.photos/seed/demo-sreymom-keo-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sreymom-keo-portfolio-2-img1/900/600","caption":"Policy brief cover"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('8046dbbb-fba5-5f38-8733-dda062a5d0ff', '580a10e5-1ad7-58bd-8b50-01b7f9c5735a', $$Marine Litter Baseline, Kampot and Kep$$, $$UN Environment Programme$$, (SELECT id FROM organizations WHERE name = $$UN Environment Programme$$), 2024, 2024, $$Research Assistant$$, $$Organised beach litter surveys at eight sites with local volunteers, classified the litter by source, and summarised options for municipal waste collection in fishing villages.$$, $$Baseline published; two municipalities extended waste collection to coastal villages.$$, $$[{"url":"https://picsum.photos/seed/demo-sreymom-keo-marine-litter-baseline-kampot-and-kep-1/900/600","caption":"Beach litter survey in Kep"},{"url":"https://picsum.photos/seed/demo-sreymom-keo-marine-litter-baseline-kampot-and-kep-2/900/600","caption":"Sorting litter by source"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('a8932615-6c42-5be2-9bb9-ac48d9058ead', '580a10e5-1ad7-58bd-8b50-01b7f9c5735a', $$ee52a122-6bd1-40b6-9ac3-b84b16526e40$$, NULL, $$Sophea Chan$$, $$UNDP$$, $$Programme Analyst, Environment$$, $$client$$, $$sophea.chan@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2023, $$Plastic waste flow analysis in Phnom Penh markets$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We worked with Sreymom on the plastic waste flow analysis in Phnom Penh markets. She organised the market surveys carefully and her analysis was clear and well sourced. She also wrote a policy brief that the environment ministry used in its extended producer responsibility discussions. I would work with her again on circular economy research.$$, $$auto$$, '2026-08-19T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-17T16:49:08.421Z'::timestamptz, '2026-08-19T16:34:44.421Z'::timestamptz, '2026-08-19T16:41:56.421Z'::timestamptz, '2026-08-19T16:49:08.421Z'::timestamptz, '2026-08-19T16:49:08.421Z'::timestamptz, '2026-08-20T16:49:08.421Z'::timestamptz, $$8edb2177543220852f98f2f4a30a4324$$, '2026-08-16T16:49:08.421Z'::timestamptz);
