-- Thiri Aung Khin
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('2af22004-f374-4dfd-b538-81e2c554ed5e', '134e6ab8-7482-5723-bd65-ce35cf616fc7', $$Social Cohesion Among Displaced and Host Communities$$, $$Humanitarian donor consortium$$, NULL, 2022, 2023, $$Research Lead$$, $$Led qualitative research on relations between displaced people and host villages in the south-east, through local research partners.$$, $$Findings shaped conflict-sensitive aid distribution guidelines.$$, $$[{"url":"https://picsum.photos/seed/demo-thiri-aung-khin-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-thiri-aung-khin-portfolio-1-img1/900/600","caption":"Research partner training (remote)"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('25f4369e-f2c4-4f83-9e37-7751accebdfb', '134e6ab8-7482-5723-bd65-ce35cf616fc7', $$Local Ceasefire Monitoring Review$$, $$Myanmar peace support organization$$, NULL, 2018, 2019, $$Researcher$$, $$Reviewed community-based ceasefire monitoring mechanisms in two states.$$, $$Review informed training for community monitors.$$, $$[{"url":"https://picsum.photos/seed/demo-thiri-aung-khin-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-thiri-aung-khin-portfolio-2-img1/900/600","caption":"Community monitors meeting"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('71f01221-5e51-5402-bfdf-e4ef1b08fc0d', '134e6ab8-7482-5723-bd65-ce35cf616fc7', $$Political Economy of Local Governance, Mon State$$, $$The Asia Foundation$$, (SELECT id FROM organizations WHERE name = $$The Asia Foundation$$), 2019, 2020, $$Lead Researcher$$, $$Led a political economy study of township administration and local service delivery in Mon State, based on interviews with administrators, ethnic armed organisation representatives and community leaders.$$, $$Findings informed the design of a local governance support programme in two states.$$, $$[{"url":"https://picsum.photos/seed/demo-thiri-aung-khin-political-economy-of-local-governance-mo-1/900/600","caption":"Interview with a village tract administrator"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('3bed0fa0-b2d3-567d-b386-29fbb3de181f', '134e6ab8-7482-5723-bd65-ce35cf616fc7', $$f6e7e393-9d6a-4aa1-9c0c-563fb488362c$$, NULL, $$Khin Mar Lwin$$, $$The Asia Foundation$$, $$Senior Program Officer$$, $$supervisor$$, $$khinmar.lwin@asiafoundation.org$$, (SELECT id FROM organizations WHERE name = $$The Asia Foundation$$), 2015, 2021, $$Peace process research in Myanmar$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Thiri at a Myanmar peace support organisation before joining The Asia Foundation. Her conflict analysis was always balanced and grounded in long conversations with people on all sides. She is careful about the safety of everyone she interviews. I would work with her again on peacebuilding and social cohesion research.$$, $$auto$$, '2026-03-27T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-03-25T16:49:08.421Z'::timestamptz, '2026-03-27T16:34:44.421Z'::timestamptz, '2026-03-27T16:41:56.421Z'::timestamptz, '2026-03-27T16:49:08.421Z'::timestamptz, '2026-03-27T16:49:08.421Z'::timestamptz, '2026-03-28T16:49:08.421Z'::timestamptz, $$e8b4ebcf256d221a75115d763863f1f2$$, '2026-03-24T16:49:08.421Z'::timestamptz);
