INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('a89c62ca-1b89-472a-992a-ef8043b3d134', 'fbdebe0c-c81c-5ab3-bf72-af17a8638e24', $$Community Legal Information Sessions, Ermera and Liquiçá$$, $$The Asia Foundation$$, (SELECT id FROM organizations WHERE name = $$The Asia Foundation$$), 2022, 2024, $$Programme Assistant$$, $$Organized community sessions on land rights and domestic violence law with public outreach materials in Tetum.$$, $$110 sessions reached about 6,000 people.$$, $$[{"url":"https://picsum.photos/seed/demo-joana-ximenes-soares-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-joana-ximenes-soares-portfolio-1-img1/900/600","caption":"Community legal session in Ermera"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('63de8452-fd4b-4405-ba83-5f6f4e67e8e2', 'fbdebe0c-c81c-5ab3-bf72-af17a8638e24', $$Municipal Development Plan Consultations$$, $$Ministry of State Administration, Timor-Leste$$, NULL, 2023, 2023, $$Facilitator and Interpreter$$, $$Supported citizen engagement in municipal planning consultations, interpreting between Tetum and Portuguese.$$, $$Consultation inputs incorporated into two municipal plans.$$, $$[{"url":"https://picsum.photos/seed/demo-joana-ximenes-soares-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-joana-ximenes-soares-portfolio-2-img1/900/600","caption":"Consultation in Liquiçá"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('c1eb104d-fb9f-5dc4-a5e8-c0d1e5cbe3d4', 'fbdebe0c-c81c-5ab3-bf72-af17a8638e24', $$Plain-Language Guide to Land Rights in Tetum$$, $$The Asia Foundation$$, (SELECT id FROM organizations WHERE name = $$The Asia Foundation$$), 2024, 2025, $$Translator and Editor$$, $$Translated and edited a plain-language guide to land rights and dispute resolution in Tetum, tested it with community paralegals, and prepared a short version for community radio.$$, $$Guide used by 60 community paralegals in five municipalities.$$, $$[{"url":"https://picsum.photos/seed/demo-joana-ximenes-soares-plain-language-guide-to-land-rights-in-t-1/900/600","caption":"Testing the guide with paralegals"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
