-- Aigerim Toktogulova
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('cd68d213-4f33-4cb3-9f6b-731261a33f24', 'd953913c-a01a-5835-81a7-c5e81f24db6f', $$Public Building Retrofit Programme$$, $$UNDP Kyrgyzstan$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2017, 2020, $$Project Coordinator$$, $$Coordinated energy efficiency retrofits of 40 schools and clinics and facilitated municipal co-financing.$$, $$Average heating energy use in retrofitted buildings fell by 35%.$$, $$[{"url":"https://picsum.photos/seed/demo-aigerim-toktogulova-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-aigerim-toktogulova-portfolio-1-img1/900/600","caption":"Retrofitted school in Naryn"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('7d90f6e2-3496-4d98-ac6a-9405223cfacf', 'd953913c-a01a-5835-81a7-c5e81f24db6f', $$Clean Heating Options for Rural Households$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2022, 2023, $$Consultant$$, $$Assessed clean heating alternatives to coal stoves and consulted households and suppliers.$$, $$Findings informed a pilot of efficient stoves and insulation subsidies.$$, $$[{"url":"https://picsum.photos/seed/demo-aigerim-toktogulova-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-aigerim-toktogulova-portfolio-2-img1/900/600","caption":"Household consultation in Issyk-Kul"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('3c105c81-7717-50eb-a9e8-d25ba602c171', 'd953913c-a01a-5835-81a7-c5e81f24db6f', $$Coal Heating and Air Quality Study, Bishkek$$, $$UN Environment Programme$$, (SELECT id FROM organizations WHERE name = $$UN Environment Programme$$), 2024, 2024, $$Energy Efficiency Specialist$$, $$Estimated household coal use in Bishkek's private housing areas, its contribution to winter air pollution, and the cost of switching to insulated homes with heat pumps or district heating connections.$$, $$Study informed the city's clean air plan and a pilot subsidy for 500 households.$$, $$[{"url":"https://picsum.photos/seed/demo-aigerim-toktogulova-coal-heating-and-air-quality-study-bishk-1/900/600","caption":"Household energy survey"},{"url":"https://picsum.photos/seed/demo-aigerim-toktogulova-coal-heating-and-air-quality-study-bishk-2/900/600","caption":"Winter air quality monitoring"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
