INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('45f78bae-8b07-4dd3-b893-4a5e567d0150', 'd9a829d6-fde0-5ef0-a2ee-40506fae22c1', $$Export Diversification Indicators$$, $$Uzbek government economic think tank$$, NULL, 2023, 2024, $$Analyst$$, $$Built export diversification and product complexity indicators from customs data using R.$$, $$Indicators included in the annual export strategy review.$$, $$[{"url":"https://picsum.photos/seed/demo-sherzod-yuldashev-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sherzod-yuldashev-portfolio-1-img1/900/600","caption":"Export indicator dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('722778e2-7eca-4df7-990a-efbf816240a2', 'd9a829d6-fde0-5ef0-a2ee-40506fae22c1', $$Logistics Performance Along Central Asian Corridors$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2022, 2023, $$Research Assistant$$, $$Compiled border crossing times and freight costs along regional corridors and produced statistical summaries.$$, $$Data used in a regional corridor performance report.$$, $$[{"url":"https://picsum.photos/seed/demo-sherzod-yuldashev-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-sherzod-yuldashev-portfolio-2-img1/900/600","caption":"Border crossing at Oybek"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('f47173c1-f453-54bd-bbed-981fb230339f', 'd9a829d6-fde0-5ef0-a2ee-40506fae22c1', $$Border Crossing Time Survey, Uzbekistan–Kazakhstan$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2024, 2024, $$Data Analyst$$, $$Analysed GPS truck data and border post records to measure crossing times at three Uzbekistan–Kazakhstan border posts, and built a dashboard showing delays by time of day and type of cargo.$$, $$Dashboard used by the customs committee to plan staffing at peak hours.$$, $$[{"url":"https://picsum.photos/seed/demo-sherzod-yuldashev-border-crossing-time-survey-uzbekistan-k-1/900/600","caption":"Truck queue at the border post"},{"url":"https://picsum.photos/seed/demo-sherzod-yuldashev-border-crossing-time-survey-uzbekistan-k-2/900/600","caption":"Dashboard review"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
