-- Ananya Bhattacharya
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('640fdc33-db44-4fd9-b9f5-ce51c9dda2d6', '72fc8f18-214f-5760-8535-db3d504e2c06', $$Working Paper Series on Learning Outcomes$$, $$Indian education research centre$$, NULL, 2023, 2024, $$Editor$$, $$Edited twelve working papers on foundational learning and teacher policy for publication.$$, $$Series published on schedule; two papers accepted in peer-reviewed journals.$$, $$[{"url":"https://picsum.photos/seed/demo-ananya-bhattacharya-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-ananya-bhattacharya-portfolio-1-img1/900/600","caption":"Working paper series covers"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('43872371-4a26-41f7-a1b2-4d851879cd99', '72fc8f18-214f-5760-8535-db3d504e2c06', $$Policy Briefs from a Health Financing Report$$, $$Health policy think tank$$, NULL, 2022, 2022, $$Writer$$, $$Drafted four policy briefs from a 200-page report on state health financing.$$, $$Briefs used in state budget consultations.$$, $$[{"url":"https://picsum.photos/seed/demo-ananya-bhattacharya-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-ananya-bhattacharya-portfolio-2-img1/900/600","caption":"Policy brief layout"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('89f17a55-dcb3-53d3-a612-e012b10ab893', '72fc8f18-214f-5760-8535-db3d504e2c06', $$Evidence Summaries on School Meals and Learning$$, $$Institute of Development Studies$$, (SELECT id FROM organizations WHERE name = $$Institute of Development Studies$$), 2024, 2024, $$Writer and Editor$$, $$Wrote eight two-page evidence summaries on school meals, attendance and learning outcomes in South Asia, based on a systematic review, for state education officials.$$, $$Summaries used in two state-level consultations on school meal reform.$$, $$[{"url":"https://picsum.photos/seed/demo-ananya-bhattacharya-evidence-summaries-on-school-meals-and-l-1/900/600","caption":"Evidence summary series"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('1ebc0332-0acb-5a00-9aff-9ddf2230e061', '72fc8f18-214f-5760-8535-db3d504e2c06', $$586e1f3a-34a5-4fe2-bf88-966a853a3ce3$$, NULL, $$Dr. Sudipta Sen$$, $$Institute of Development Studies$$, $$Research Fellow$$, $$supervisor$$, $$s.sen@ids.ac.uk$$, (SELECT id FROM organizations WHERE name = $$Institute of Development Studies$$), 2020, 2023, $$Editing at an economics and policy journal in Kolkata$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Ananya's editor at the journal in Kolkata before I moved to IDS. She edited dense economics papers into clear prose without losing the argument, and authors asked for her by name. She is fast, careful and tactful. I would work with her again on research editing and policy writing.$$, $$auto$$, '2026-05-21T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-19T16:49:08.421Z'::timestamptz, '2026-05-21T16:34:44.421Z'::timestamptz, '2026-05-21T16:41:56.421Z'::timestamptz, '2026-05-21T16:49:08.421Z'::timestamptz, '2026-05-21T16:49:08.421Z'::timestamptz, '2026-05-22T16:49:08.421Z'::timestamptz, $$fcc63f5ee0c5dacb094c2de62dcab1a7$$, '2026-05-18T16:49:08.421Z'::timestamptz);
