INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('0e4fff86-07c9-4900-a0f8-35676125121b', 'acdfbc21-791f-52cf-8954-50c0214e229e', $$Social Registry Data Platform, Odisha$$, $$State Government of Odisha$$, NULL, 2019, 2021, $$Lead Data Engineer$$, $$Designed the data platform linking social protection schemes to a single registry, with payment reconciliation and deduplication.$$, $$Platform covers 9 million households; duplicate payments fell sharply.$$, $$[{"url":"https://picsum.photos/seed/demo-kavya-subramanian-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-kavya-subramanian-portfolio-1-img1/900/600","caption":"Registry architecture review"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('33c6d94f-3c92-4ddd-bbdc-15f76f1e5657', 'acdfbc21-791f-52cf-8954-50c0214e229e', $$Cloud Hosting and Cybersecurity Review for a Social Registry$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2023, 2024, $$Cloud Architect$$, $$Assessed hosting options and cybersecurity controls for an African government's social registry.$$, $$Government adopted a hybrid hosting model with a sovereign data centre.$$, $$[{"url":"https://picsum.photos/seed/demo-kavya-subramanian-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-kavya-subramanian-portfolio-2-img1/900/600","caption":"Remote architecture workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('54a569e1-c54e-5329-8a05-e638c1985ebd', 'acdfbc21-791f-52cf-8954-50c0214e229e', $$Payment Reconciliation Pipeline for Social Pensions, Tamil Nadu$$, $$State Government of Tamil Nadu$$, NULL, 2022, 2023, $$Data Architect$$, $$Designed a data pipeline that reconciles pension payment files from banks with the beneficiary registry every month, flags failed payments and duplicates, and feeds a dashboard for district officers.$$, $$Failed payments resolved within 10 days instead of three months; 18,000 duplicate records removed.$$, $$[{"url":"https://picsum.photos/seed/demo-kavya-subramanian-payment-reconciliation-pipeline-for-soci-1/900/600","caption":"Reconciliation dashboard"},{"url":"https://picsum.photos/seed/demo-kavya-subramanian-payment-reconciliation-pipeline-for-soci-2/900/600","caption":"Training for district officers"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('18013a74-c147-5838-afb3-1d5f8a1cfe84', 'acdfbc21-791f-52cf-8954-50c0214e229e', $$Data Protection Impact Assessment for a Social Registry$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2024, 2024, $$Lead Assessor$$, $$Assessed a national social registry's data flows, access controls and consent practices against data protection law, and set out a remediation plan for encryption, access logging and data minimisation.$$, $$Remediation plan adopted; access logging live within six months.$$, $$[{"url":"https://picsum.photos/seed/demo-kavya-subramanian-data-protection-impact-assessment-for-a--1/900/600","caption":"Data flow mapping workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('aca11a1f-4449-57a2-a336-f2004fb30f4e', 'acdfbc21-791f-52cf-8954-50c0214e229e', $$8390376c-a63d-4ca7-927b-cd96c07b7c6a$$, NULL, $$Ravi Krishnan$$, $$Thoughtworks$$, $$Principal Engineer$$, $$supervisor$$, $$ravi.krishnan@thoughtworks.com$$, (SELECT id FROM organizations WHERE name = $$Thoughtworks$$), 2015, 2021, $$Data engineering for public sector clients$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Kavya's engineering manager for six years before I joined Thoughtworks. She built data pipelines for government clients that were secure, well tested and easy to hand over. She is the person I would trust with sensitive public data. I would work with her again on data platforms for social programmes.$$, $$auto$$, '2026-04-26T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-04-24T16:49:08.421Z'::timestamptz, '2026-04-26T16:34:44.421Z'::timestamptz, '2026-04-26T16:41:56.421Z'::timestamptz, '2026-04-26T16:49:08.421Z'::timestamptz, '2026-04-26T16:49:08.421Z'::timestamptz, '2026-04-27T16:49:08.421Z'::timestamptz, $$0c8ec96a3b18e100998c587d6c6b9851$$, '2026-04-23T16:49:08.421Z'::timestamptz);
