INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('c6b595cd-c59a-5b44-bc1e-4a551c7367ec', 'acdfbc21-791f-52cf-8954-50c0214e229e', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the social registry data platform in Odisha. I designed the data architecture. What changed is that eligibility checks that took weeks now run overnight, and households stopped being dropped because of data errors.$$, 20),
  ('2a36c054-2336-5666-a4e4-8f279d101b7e', 'acdfbc21-791f-52cf-8954-50c0214e229e', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] When I reviewed a social registry in a country I had never worked in, I started with the people who enter the data at district level. Their workarounds told me where the real risks were.$$, 20),
  ('54ad0b5f-2a6d-573a-ae6e-8f4f0abd8945', 'acdfbc21-791f-52cf-8954-50c0214e229e', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] In one review I had to tell the client that their cloud setup exposed beneficiary data. I explained the risk calmly, with a short list of fixes in order of urgency, and offered to help the team implement the first ones.$$, 20),
  ('badcb3db-def2-5888-bb21-46c7166be25f', 'acdfbc21-791f-52cf-8954-50c0214e229e', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work across Indian states with different languages and administrative cultures. I make sure local IT staff own the system, and I write documentation in plain language they can use after I leave.$$, 20),
  ('f8f5cbb6-c3ba-5f88-9161-ef53cffe122c', 'acdfbc21-791f-52cf-8954-50c0214e229e', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in data pipelines for social programmes. They are not the right tool when the underlying data is collected badly; then you need to fix data collection first, not automate the errors.$$, 20);
