  ('77e9a3c7-95e4-500c-a1b7-070b66e598fa', 'acdfbc21-791f-52cf-8954-50c0214e229e', 'degree', $$7614c5a3-ce17-43ce-a5ff-e62a80be0e9e$$, $$BTech Computer Science, National Institute of Technology Tiruchirappalli, 2011–2015$$, '50328f89', 'document_reviewed', 'document', $${"note":"Demo: certificate checked for format, dates and consistency.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-04-01T21:49:08.421Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-04-01T22:49:08.421Z'::timestamptz),
