INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('cddd3fbe-0187-4a1f-a374-5d11ba33d98f', '9d5b1987-38c1-522f-9fcc-951e7224328b', $$Safe Routes to School Programme, Bogotá$$, $$Bloomberg Philanthropies Initiative for Global Road Safety$$, (SELECT id FROM organizations WHERE name = $$Bloomberg Philanthropies$$), 2020, 2022, $$Road Safety Planner$$, $$Mapped crash hotspots near 80 schools with GIS and designed traffic calming with parents and teachers.$$, $$Pedestrian injuries near treated schools fell by a third.$$, $$[{"url":"https://picsum.photos/seed/demo-mariana-ospina-restrepo-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mariana-ospina-restrepo-portfolio-1-img1/900/600","caption":"Traffic calming near a school in Kennedy"},{"url":"https://picsum.photos/seed/demo-mariana-ospina-restrepo-portfolio-1-img2/900/600","caption":"Walking audit with students"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('7d788019-a38b-4d74-b855-ffcb493bb170', '9d5b1987-38c1-522f-9fcc-951e7224328b', $$Accessibility Analysis for Quito's Cycling Network$$, $$Inter-American Development Bank$$, (SELECT id FROM organizations WHERE name = $$Inter-American Development Bank$$), 2023, 2023, $$GIS Lead$$, $$Analysed job accessibility by bicycle and public transport to prioritize new cycling corridors.$$, $$Three priority corridors included in the city mobility plan.$$, $$[{"url":"https://picsum.photos/seed/demo-mariana-ospina-restrepo-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mariana-ospina-restrepo-portfolio-2-img1/900/600","caption":"Cycling corridor accessibility map"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('b0ba72f8-8124-57c3-9bd2-f603f98c44e0', '9d5b1987-38c1-522f-9fcc-951e7224328b', $$Cable Car Feeder Network Plan, La Paz$$, $$CAF Development Bank of Latin America$$, (SELECT id FROM organizations WHERE name = $$CAF Development Bank of Latin America$$), 2021, 2022, $$Lead Mobility Planner$$, $$Planned feeder bus and walking routes to three new cable car stations in La Paz and El Alto, using GIS accessibility analysis and walking audits with residents, including older people and people with disabilities.$$, $$Two feeder routes and 14 kilometres of improved footpaths included in the municipal investment plan.$$, $$[{"url":"https://picsum.photos/seed/demo-mariana-ospina-restrepo-cable-car-feeder-network-plan-la-paz-1/900/600","caption":"Walking audit with residents in El Alto"},{"url":"https://picsum.photos/seed/demo-mariana-ospina-restrepo-cable-car-feeder-network-plan-la-paz-2/900/600","caption":"Accessibility map"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
