INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('6f2e287c-5866-43c7-a331-f398c77db38c', '7f19fdb3-785a-533a-b8e7-c77fa3bcd616', $$Native Potato Biodiversity and Climate Study$$, $$FAO Peru$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2021, 2022, $$Field Research Lead$$, $$Led qualitative research with six Quechua communities on native potato varieties, seed exchange and climate change.$$, $$Study supported recognition of a community agrobiodiversity zone.$$, $$[{"url":"https://picsum.photos/seed/demo-rosa-quispe-mamani-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rosa-quispe-mamani-portfolio-1-img1/900/600","caption":"Seed fair in Pisac"},{"url":"https://picsum.photos/seed/demo-rosa-quispe-mamani-portfolio-1-img2/900/600","caption":"Interview with a community seed keeper"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('2972bca9-a6e3-49b9-a611-1593a0c71e4f', '7f19fdb3-785a-533a-b8e7-c77fa3bcd616', $$Prior Consultation Interpretation for an Irrigation Project$$, $$Ministry of Culture, Peru$$, NULL, 2019, 2019, $$Quechua Interpreter$$, $$Interpreted community assemblies during a prior consultation process for an irrigation project.$$, $$Agreements recorded in Quechua and Spanish; consultation completed with community consent.$$, $$[{"url":"https://picsum.photos/seed/demo-rosa-quispe-mamani-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rosa-quispe-mamani-portfolio-2-img1/900/600","caption":"Community assembly in Apurímac"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('6e8db562-f20a-5a8e-9298-71c28954e701', '7f19fdb3-785a-533a-b8e7-c77fa3bcd616', $$Community Seed Bank Documentation, Potato Park$$, $$IFAD$$, (SELECT id FROM organizations WHERE name = $$IFAD$$), 2023, 2024, $$Researcher$$, $$Documented how six Quechua communities manage their community seed banks and exchange native potato varieties, recording farmers' own criteria for selection in Quechua and Spanish.$$, $$Documentation used to register the seed banks with the national agricultural research institute.$$, $$[{"url":"https://picsum.photos/seed/demo-rosa-quispe-mamani-community-seed-bank-documentation-potato-1/900/600","caption":"Seed bank in the Potato Park"},{"url":"https://picsum.photos/seed/demo-rosa-quispe-mamani-community-seed-bank-documentation-potato-2/900/600","caption":"Farmer interviews in Quechua"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
