-- Beatriz Nogueira Lima
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('96b4cd17-ddd4-4682-9a72-ad3bb3d4fd1c', '02174de5-f172-5594-a5e1-ab29b735538d', $$Impact Evaluation of an Early Childhood Home-Visiting Programme$$, $$Inter-American Development Bank$$, (SELECT id FROM organizations WHERE name = $$Inter-American Development Bank$$), 2019, 2022, $$Principal Investigator$$, $$Randomized impact evaluation of home visits linked to cash transfer families in three Brazilian states.$$, $$Found gains in child development scores; programme scaled to 2,000 municipalities.$$, $$[{"url":"https://picsum.photos/seed/demo-beatriz-nogueira-lima-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-beatriz-nogueira-lima-portfolio-1-img1/900/600","caption":"Home visit in Ceará"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('4c657195-010f-47aa-a339-8fa1775ac526', '02174de5-f172-5594-a5e1-ab29b735538d', $$Cash Transfer Design Support, Mozambique$$, $$UNICEF Mozambique$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2023, 2024, $$Policy Advisor$$, $$Advised on targeting and benefit design for a child grant using evidence from Brazil and the region.$$, $$Design adopted in the national basic social security strategy.$$, $$[{"url":"https://picsum.photos/seed/demo-beatriz-nogueira-lima-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-beatriz-nogueira-lima-portfolio-2-img1/900/600","caption":"Workshop in Maputo"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('ccb4ba8c-626f-5322-b0a8-1d57ef666d4d', '02174de5-f172-5594-a5e1-ab29b735538d', $$Social Assistance Monitoring System, Brazil$$, $$Ministério do Desenvolvimento Social, Brazil$$, NULL, 2012, 2016, $$Evaluation Coordinator$$, $$Coordinated the design of the ministry's monitoring system for social assistance services: indicators for municipal social assistance centres, a data platform shared with municipalities, and quarterly performance reports.$$, $$All 5,500 municipalities reporting quarterly by 2015; reports used in federal transfers to municipalities.$$, $$[{"url":"https://picsum.photos/seed/demo-beatriz-nogueira-lima-social-assistance-monitoring-system-braz-1/900/600","caption":"Municipal reporting workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('7a0973d1-db68-5c64-a4fb-53c33d6c8350', '02174de5-f172-5594-a5e1-ab29b735538d', $$Social Pension Reform Options, Paraguay$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2018, 2019, $$Senior Social Protection Consultant$$, $$Costed options for reforming Paraguay's non-contributory social pension: eligibility age, benefit indexation and links to the contributory system, with a fiscal projection to 2040 for the finance ministry.$$, $$Indexation rule adopted in the 2020 budget law.$$, $$[{"url":"https://picsum.photos/seed/demo-beatriz-nogueira-lima-social-pension-reform-options-paraguay-1/900/600","caption":"Fiscal projection workshop in Asunción"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('17e7b390-586b-5ad1-8761-ec6e075e50f0', '02174de5-f172-5594-a5e1-ab29b735538d', $$7837bb59-e3e3-461a-ba83-3cbf174bd5c0$$, NULL, $$Dr. Ricardo Paes$$, $$World Bank$$, $$Lead Economist$$, $$supervisor$$, $$rpaes@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2009, 2017, $$Evaluation at Brazil's social development ministry$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I directed the evaluation department where Beatriz coordinated our evaluation agenda, before I joined the World Bank. She designed evaluations that answered the questions policymakers were actually asking, and she defended their independence. She is one of the best social protection evaluators in Latin America. I would work with her again.$$, $$auto$$, '2026-05-26T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-24T16:49:08.421Z'::timestamptz, '2026-05-26T16:34:44.421Z'::timestamptz, '2026-05-26T16:41:56.421Z'::timestamptz, '2026-05-26T16:49:08.421Z'::timestamptz, '2026-05-26T16:49:08.421Z'::timestamptz, '2026-05-27T16:49:08.421Z'::timestamptz, $$0453c6d6d432a39fe9976b31ef2913ee$$, '2026-05-23T16:49:08.421Z'::timestamptz);
