INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('200828df-c74c-565c-ae6c-932c125f05c3', '02174de5-f172-5594-a5e1-ab29b735538d', NULL, '96b4cd17-ddd4-4682-9a72-ad3bb3d4fd1c', $$Laura Ibarra$$, $$Inter-American Development Bank$$, $$Senior Social Protection Specialist$$, $$client$$, $$lauraib@iadb.org$$, (SELECT id FROM organizations WHERE name = $$Inter-American Development Bank$$), 2019, 2022, $$Impact evaluation of an early childhood home-visiting programme$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We contracted Beatriz to lead the impact evaluation of an early childhood home-visiting programme. She managed a large team, kept the randomisation intact through a difficult roll-out, and presented results the government could use. I would work with her again on early childhood and social protection evaluations.$$, $$auto$$, '2026-08-14T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-14T16:34:44.421Z'::timestamptz, '2026-08-14T16:41:56.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-15T16:49:08.421Z'::timestamptz, $$27bc4d389cd31e670be799e268fd5ebb$$, '2026-08-11T16:49:08.421Z'::timestamptz);
