INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('8e7b126f-4dfb-55dc-a5aa-4709f0e51afb', '02174de5-f172-5594-a5e1-ab29b735538d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the evaluation agenda at Brazil's social development ministry. I coordinated fourteen evaluations. What changed is that evaluation became routine: findings fed directly into benefit levels and conditionality monitoring.$$, 20),
  ('0f5a8849-15d3-5ff3-abf3-e08754d4560b', '02174de5-f172-5594-a5e1-ab29b735538d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Mozambique I supported cash transfer design in a very different institutional context. I listened to district social action officers first, because they knew what was feasible, and adjusted the design to their capacity.$$, 20),
  ('9bed8603-be20-547e-a2e5-60c3f231c11d', '02174de5-f172-5594-a5e1-ab29b735538d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When an evaluation found no effect on learning, I presented it to the ministry together with the positive effects on attendance and a clear explanation of why learning did not move, so the result led to better programme design.$$, 20),
  ('15bff539-235b-5d07-89c1-7c3caff21bce', '02174de5-f172-5594-a5e1-ab29b735538d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Portuguese, Spanish and English. I always build teams with local researchers, and I make sure the evaluation questions are agreed with the people who run the programme.$$, 20),
  ('2ac4f1c8-2a1d-569d-8e03-b0c38b0468a5', '02174de5-f172-5594-a5e1-ab29b735538d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in quasi-experimental evaluation. It is not the right tool when the programme is still changing every month; then a process evaluation is more useful.$$, 20);
