INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('7dabefb7-9f12-49e6-ad19-5e434896daa2', '70c1e3de-d2ab-5d27-9e09-cd1654aeda5e', $$Wind Curtailment Analysis, North-East Brazil$$, $$State energy agency (Pernambuco)$$, NULL, 2023, 2024, $$Data Analyst$$, $$Analysed curtailment of wind generation using hourly grid data in Python.$$, $$Analysis supported a request for transmission upgrades.$$, $$[{"url":"https://picsum.photos/seed/demo-rafael-tavares-moura-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rafael-tavares-moura-portfolio-1-img1/900/600","caption":"Wind farm in the sertão"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('0fa2695f-2716-457e-96da-3711c9375b60', '70c1e3de-d2ab-5d27-9e09-cd1654aeda5e', $$Distributed Solar for Public Schools$$, $$Universidade Federal de Pernambuco$$, (SELECT id FROM organizations WHERE name = $$Universidade Federal de Pernambuco$$), 2021, 2022, $$Research Assistant$$, $$Modelled generation and payback for rooftop solar on 200 public schools.$$, $$Model used in the state's solar schools tender.$$, $$[{"url":"https://picsum.photos/seed/demo-rafael-tavares-moura-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rafael-tavares-moura-portfolio-2-img1/900/600","caption":"Rooftop solar installation"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('817344cb-b5c8-5f48-bf4b-c2c465344970', '70c1e3de-d2ab-5d27-9e09-cd1654aeda5e', $$Grid Hosting Capacity Map for Rooftop Solar, Recife$$, $$Universidade Federal de Pernambuco$$, (SELECT id FROM organizations WHERE name = $$Universidade Federal de Pernambuco$$), 2022, 2022, $$Research Assistant$$, $$Built a hosting capacity map showing how much rooftop solar each feeder of Recife's distribution network could absorb, using load data from the utility and open building footprints.$$, $$Map shared with the utility and used to prioritise two feeder upgrades.$$, $$[{"url":"https://picsum.photos/seed/demo-rafael-tavares-moura-grid-hosting-capacity-map-for-rooftop-so-1/900/600","caption":"Hosting capacity map"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
