INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('c04fc9fd-8773-47d8-84f9-d2b99bc21fee', '56cbb2d3-a0f7-5dee-8825-8623abe152d3', $$Integration Survey of Venezuelan Refugees and Migrants$$, $$UNHCR Ecuador$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2022, 2023, $$Survey Lead$$, $$Designed and analysed a survey of 2,000 households on livelihoods, documentation and access to services.$$, $$Results informed municipal integration plans in Quito and Guayaquil.$$, $$[{"url":"https://picsum.photos/seed/demo-gabriela-andrade-paredes-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-gabriela-andrade-paredes-portfolio-1-img1/900/600","caption":"Survey team in Quito"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('e482a8ab-3f76-44ba-befc-27b1c092cae6', '56cbb2d3-a0f7-5dee-8825-8623abe152d3', $$Social Cohesion in Border Towns$$, $$Danish Refugee Council$$, (SELECT id FROM organizations WHERE name = $$Danish Refugee Council$$), 2021, 2021, $$Researcher$$, $$Qualitative research on relations between Venezuelan migrants and host communities in Tulcán and Huaquillas.$$, $$Recommendations used to design community dialogue activities.$$, $$[{"url":"https://picsum.photos/seed/demo-gabriela-andrade-paredes-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-gabriela-andrade-paredes-portfolio-2-img1/900/600","caption":"Focus group in Tulcán"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('a76e8028-cae6-5cc5-b3b0-554ec04ed509', '56cbb2d3-a0f7-5dee-8825-8623abe152d3', $$Deduplication of Cash Assistance Lists, Ecuador$$, $$IOM$$, (SELECT id FROM organizations WHERE name = $$IOM$$), 2020, 2021, $$Information Management Coordinator$$, $$Set up a shared protocol and secure matching process so that partners giving cash to Venezuelan refugees and migrants in Ecuador could find duplicate beneficiaries without exchanging personal data.$$, $$Duplicate assistance fell by 22%; protocol adopted by the national cash working group.$$, $$[{"url":"https://picsum.photos/seed/demo-gabriela-andrade-paredes-deduplication-of-cash-assistance-lists-e-1/900/600","caption":"Cash working group session"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('92c810b5-1be6-57f1-860c-7980cf5d78ea', '56cbb2d3-a0f7-5dee-8825-8623abe152d3', $$f81a6cf8-f1e5-4343-9a36-55250c83364c$$, NULL, $$Andrés Villacís$$, $$IOM$$, $$Information Management Officer$$, $$supervisor$$, $$avillacis@iom.int$$, (SELECT id FROM organizations WHERE name = $$IOM$$), 2018, 2021, $$Information management for the refugee and migrant response platform$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Gabriela when she coordinated information management for the refugee and migrant response platform in Ecuador, before I moved to IOM. She built systems that dozens of partners actually used, and she was careful with personal data. Her integration survey work since then is excellent. I would work with her again on migration research.$$, $$auto$$, '2026-06-30T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-28T16:49:08.421Z'::timestamptz, '2026-06-30T16:34:44.421Z'::timestamptz, '2026-06-30T16:41:56.421Z'::timestamptz, '2026-06-30T16:49:08.421Z'::timestamptz, '2026-06-30T16:49:08.421Z'::timestamptz, '2026-07-01T16:49:08.421Z'::timestamptz, $$ba2d1bea141a4f811ccd8fada3730e64$$, '2026-06-27T16:49:08.421Z'::timestamptz);
