-- Widline Pierre-Louis
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('6baffc07-10de-4f3a-bd9b-70c6b6ae1c49', 'f64f6f86-2408-52d4-8ac6-41b561567ba0', $$Hurricane Matthew Shelter and WASH Recovery, Grand'Anse$$, $$European Commission (ECHO)$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2017, 2019, $$Project Manager$$, $$Managed reconstruction of 1,800 shelters and community water points with local committees.$$, $$All shelters completed before the next hurricane season.$$, $$[{"url":"https://picsum.photos/seed/demo-widline-pierre-louis-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-widline-pierre-louis-portfolio-1-img1/900/600","caption":"Shelter reconstruction in Jérémie"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('4a72f55f-4226-407f-ba20-e8b71c28b4a1', 'f64f6f86-2408-52d4-8ac6-41b561567ba0', $$Displacement Site Community Committees, Port-au-Prince$$, $$IOM Haiti$$, (SELECT id FROM organizations WHERE name = $$IOM$$), 2012, 2015, $$Coordinator and Interpreter$$, $$Coordinated committees in displacement sites and interpreted between residents and agencies.$$, $$Committees managed relocations of 6,000 families.$$, $$[{"url":"https://picsum.photos/seed/demo-widline-pierre-louis-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-widline-pierre-louis-portfolio-2-img1/900/600","caption":"Committee meeting in a displacement site"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('d228db99-a5fb-5b83-b7a1-0fd6b9fc86c2', 'f64f6f86-2408-52d4-8ac6-41b561567ba0', $$Cash for Shelter Repair after the 2021 Earthquake, Nippes$$, $$IFRC$$, (SELECT id FROM organizations WHERE name = $$IFRC$$), 2021, 2022, $$Recovery Programme Manager$$, $$Managed a cash for shelter repair programme for 2,800 households after the 2021 earthquake, with technical guidance from local masons on safer building and monitoring of repairs.$$, $$2,600 homes repaired to safer standards within nine months.$$, $$[{"url":"https://picsum.photos/seed/demo-widline-pierre-louis-cash-for-shelter-repair-after-the-2021-e-1/900/600","caption":"Mason training in Nippes"},{"url":"https://picsum.photos/seed/demo-widline-pierre-louis-cash-for-shelter-repair-after-the-2021-e-2/900/600","caption":"Repaired home inspection"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('09da1f59-66cb-5541-a8af-6cafcdcacf79', 'f64f6f86-2408-52d4-8ac6-41b561567ba0', $$7aee170c-da02-4cab-92b7-0a3722bbd334$$, NULL, $$Marie-Claude Joseph$$, $$IOM$$, $$Camp Coordination and Camp Management Officer$$, $$supervisor$$, $$mjoseph@iom.int$$, (SELECT id FROM organizations WHERE name = $$IOM$$), 2010, 2016, $$Camp coordination in Port-au-Prince after the 2010 earthquake$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Widline worked in my team after the 2010 earthquake. She set up community committees in displacement sites that gave residents a real voice, and she interpreted in difficult meetings with great tact. She is calm, organised and deeply committed to Haiti. I would work with her again on recovery and humanitarian programmes.$$, $$auto$$, '2026-05-01T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-04-29T16:49:08.421Z'::timestamptz, '2026-05-01T16:34:44.421Z'::timestamptz, '2026-05-01T16:41:56.421Z'::timestamptz, '2026-05-01T16:49:08.421Z'::timestamptz, '2026-05-01T16:49:08.421Z'::timestamptz, '2026-05-02T16:49:08.421Z'::timestamptz, $$b92fbf45fb3b26ff0047d6335a826fef$$, '2026-04-28T16:49:08.421Z'::timestamptz);
