INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('eaebbafb-9573-4beb-b152-eef070d17287', 'fec58f0d-95a0-581d-841d-7c5c9b5d7ade', $$Hurricane Preparedness Social Media Campaign$$, $$Regional climate resilience programme$$, NULL, 2023, 2023, $$Social Media Lead$$, $$Ran a preparedness campaign with short videos and copy on emergency kits and evacuation routes.$$, $$Campaign reached 1.2 million accounts in the Dominican Republic and Haiti.$$, $$[{"url":"https://picsum.photos/seed/demo-yokasta-feliz-matos-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-yokasta-feliz-matos-portfolio-1-img1/900/600","caption":"Campaign video still"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('51bd0093-d10a-4638-b383-3604915ddad8', 'fec58f0d-95a0-581d-841d-7c5c9b5d7ade', $$Coastal Community Outreach Days$$, $$Dominican Red Cross$$, NULL, 2021, 2022, $$Outreach Organizer$$, $$Organized outreach days in fishing communities on climate risks and emergency food and water stocks.$$, $$14 outreach days held with 2,500 participants.$$, $$[{"url":"https://picsum.photos/seed/demo-yokasta-feliz-matos-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-yokasta-feliz-matos-portfolio-2-img1/900/600","caption":"Outreach day in Barahona"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('e48945ed-fa8e-5eec-9b71-a50aa69fa26c', 'fec58f0d-95a0-581d-841d-7c5c9b5d7ade', $$Youth Climate Reporters Programme$$, $$UNICEF$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2024, 2024, $$Trainer and Coordinator$$, $$Trained 30 young people from coastal communities to report on climate risks with mobile phones, and edited their stories for social media and local radio during the hurricane season.$$, $$45 youth stories published; two picked up by national television.$$, $$[{"url":"https://picsum.photos/seed/demo-yokasta-feliz-matos-youth-climate-reporters-programme-1/900/600","caption":"Mobile reporting training"},{"url":"https://picsum.photos/seed/demo-yokasta-feliz-matos-youth-climate-reporters-programme-2/900/600","caption":"Youth reporter interviewing a fisher"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
