  ('10aca779-93d5-4e23-a8a5-8e8925fa5df8', 'a60c0d49-69cf-5939-8c0b-bac2fa05d355', $$Annual Meetings Keynote Speeches$$, $$Multilateral development bank$$, NULL, 2010, 2014, $$Lead Speechwriter$$, $$Wrote keynote speeches for annual meetings on jobs, governance and climate.$$, $$Speeches widely covered in international media.$$, $$[{"url":"https://picsum.photos/seed/demo-rebecca-thornton-hale-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rebecca-thornton-hale-portfolio-1-img1/900/600","caption":"Annual meetings plenary"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('b7d9f571-e76e-4d19-85b7-523a4b340bfb', 'a60c0d49-69cf-5939-8c0b-bac2fa05d355', $$Foundation President's Annual Letters$$, $$Private philanthropic foundation$$, NULL, 2018, 2024, $$Ghostwriter$$, $$Ghostwrote the foundation president's annual letters and related op-eds.$$, $$Letters published in major newspapers each year.$$, $$[{"url":"https://picsum.photos/seed/demo-rebecca-thornton-hale-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rebecca-thornton-hale-portfolio-2-img1/900/600","caption":"Annual letter cover"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('5418f02f-6197-5e90-9406-11a0b1ac60bf', 'a60c0d49-69cf-5939-8c0b-bac2fa05d355', $$Op-Ed Series on Debt and Climate$$, $$Center for Global Development$$, (SELECT id FROM organizations WHERE name = $$Center for Global Development$$), 2022, 2023, $$Ghostwriter and Editor$$, $$Wrote and placed a series of op-eds for senior fellows on debt relief and climate finance for low-income countries, timed to the annual meetings and climate summits.$$, $$Six op-eds placed in major international outlets.$$, $$[{"url":"https://picsum.photos/seed/demo-rebecca-thornton-hale-op-ed-series-on-debt-and-climate-1/900/600","caption":"Op-ed series"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
