INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('a88495b0-6575-456d-9fe7-f4e0c020136f', 'da94e4d4-5b84-5543-8e66-64631454aacc', $$Commercial and Industrial Solar Portfolio Model$$, $$Climate investment advisory$$, NULL, 2023, 2024, $$Financial Analyst$$, $$Built the financial model and emissions estimates for a portfolio of rooftop solar projects in Kenya and India.$$, $$Model supported a blended finance investment decision.$$, $$[{"url":"https://picsum.photos/seed/demo-priyanka-desai-mehra-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-priyanka-desai-mehra-portfolio-1-img1/900/600","caption":"Rooftop solar on a factory"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('1df9e6cf-61e3-4af0-9ff0-ef8a842bde1c', 'da94e4d4-5b84-5543-8e66-64631454aacc', $$Climate Fund Portfolio Analysis$$, $$Climate investment advisory$$, NULL, 2022, 2023, $$Data Analyst$$, $$Analysed mitigation project data across climate fund portfolios to benchmark costs per tonne of CO2.$$, $$Benchmarks used in client investment screening.$$, $$[{"url":"https://picsum.photos/seed/demo-priyanka-desai-mehra-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-priyanka-desai-mehra-portfolio-2-img1/900/600","caption":"Portfolio analysis chart"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('251dafe7-53a9-5af8-899e-17e7283eebac', 'da94e4d4-5b84-5543-8e66-64631454aacc', $$ESG Due Diligence Framework for a Climate Fund$$, $$Climate investment advisory (Toronto)$$, NULL, 2024, 2024, $$Analyst$$, $$Drafted the ESG due diligence checklist and impact reporting templates for a climate fund investing in solar and energy access companies in South Asia, aligned with the IFC Performance Standards.$$, $$Framework used for the fund's first four investments.$$, $$[{"url":"https://picsum.photos/seed/demo-priyanka-desai-mehra-esg-due-diligence-framework-for-a-climat-1/900/600","caption":"Due diligence checklist"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('ad5fc016-7712-5830-b408-f1bda9651a67', 'da94e4d4-5b84-5543-8e66-64631454aacc', $$f1220c74-09dd-4ebe-b2a3-d5b1f132afb1$$, NULL, $$Nikhil Shah$$, $$British International Investment$$, $$Investment Director, Climate$$, $$supervisor$$, $$nikhil.shah@bii.co.uk$$, (SELECT id FROM organizations WHERE name = $$British International Investment$$), 2021, 2022, $$Analysis for a clean energy developer in Ahmedabad$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Priyanka during her internship at a clean energy developer in Ahmedabad, before I joined BII. She built project models for solar parks that were accurate and easy to audit. She asks good questions and learns fast. I would work with her again on climate finance analysis.$$, $$auto$$, '2026-08-04T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-02T16:49:08.421Z'::timestamptz, '2026-08-04T16:34:44.421Z'::timestamptz, '2026-08-04T16:41:56.421Z'::timestamptz, '2026-08-04T16:49:08.421Z'::timestamptz, '2026-08-04T16:49:08.421Z'::timestamptz, '2026-08-05T16:49:08.421Z'::timestamptz, $$d4903cd70249c3aab5c69d89d207a8d7$$, '2026-08-01T16:49:08.421Z'::timestamptz);
