INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('4de88417-e0be-4333-baa5-7ad08782aa07', '6f6a48d2-fb5a-5d93-856b-5ce3d151d98a', $$Crisis Monitoring Dashboard$$, $$UN humanitarian data team$$, NULL, 2023, 2024, $$Developer$$, $$Built a web dashboard combining conflict events, displacement and food prices with a Python data pipeline.$$, $$Used by coordination teams in four crisis countries.$$, $$[{"url":"https://picsum.photos/seed/demo-daniel-whitfield-okoro-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-daniel-whitfield-okoro-portfolio-1-img1/900/600","caption":"Dashboard screenshot"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('52e80c57-5893-4e2e-94ca-d00649227b4c', '6f6a48d2-fb5a-5d93-856b-5ce3d151d98a', $$Fragility Indicator Database$$, $$University research lab on political violence$$, NULL, 2021, 2023, $$Research Assistant$$, $$Designed and maintained a database of fragility indicators for 60 countries.$$, $$Database underpinned two published papers.$$, $$[{"url":"https://picsum.photos/seed/demo-daniel-whitfield-okoro-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-daniel-whitfield-okoro-portfolio-2-img1/900/600","caption":"Indicator database schema"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('4da3308e-bf98-574e-bc0f-97909b3d6be7', '6f6a48d2-fb5a-5d93-856b-5ce3d151d98a', $$Conflict Early Warning Model, Sahel$$, $$Mercy Corps$$, (SELECT id FROM organizations WHERE name = $$Mercy Corps$$), 2024, 2025, $$Data Scientist$$, $$Built a model combining conflict event data, food prices and displacement figures to flag districts at risk of rising violence over the next three months, with a map dashboard for programme teams.$$, $$Model flagged three of the four districts that saw major escalation in 2025.$$, $$[{"url":"https://picsum.photos/seed/demo-daniel-whitfield-okoro-conflict-early-warning-model-sahel-1/900/600","caption":"Risk map dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
